// O tipo está certo; a lógica não.
function media(valores: readonly number[]): number {
  let total = 0;
  for (const v of valores) total += v;
  return total / (valores.length - 1); // bug: devia ser valores.length
}

const m: number = media([2, 4, 6]);
console.log(m); // 6  (o tsc aceita; o valor certo seria 4)

type IgualIngenuo<A, B> = A extends B ? (B extends A ? true : false) : false;
type Igual<A, B> =
  (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Esperar<T extends true> = T;

type a1 = IgualIngenuo<{ readonly id: 1 }, { id: 1 }>; // true    (errado)
type a2 = IgualIngenuo<any, unknown>;                  // true    (errado)
type a3 = IgualIngenuo<never, string>;                 // never
type a4 = IgualIngenuo<string | number, string>;       // boolean (distribuiu)

type b1 = Igual<{ readonly id: 1 }, { id: 1 }>;        // false
type b2 = Igual<any, unknown>;                         // false
type b3 = Igual<never, string>;                        // false
type b4 = Igual<string | number, string>;              // false

// Testes a sério: agrupados num tuplo, cada elemento é verificado.
type testes = [
  Esperar<Igual<Partial<{ id: number }>, { id?: number }>>,
  Esperar<Igual<b1, false>>,
];

// Compila sem erro: never satisfaz "extends true".
type passaSemDever = Esperar<a3>;

// Um teste falhado é um erro de compilação (TS2344):
// @ts-expect-error
type falha = Esperar<Igual<Partial<{ id: number }>, { id: number }>>;

interface Encomenda { id: number; quantidade: number }

function criarEncomenda(dados: Encomenda): Encomenda {
  return { ...dados };
}

// Chamada válida: tem de compilar.
criarEncomenda({ id: 1, quantidade: 2 });

// Cada chamada seguinte TEM de falhar.
// @ts-expect-error falta quantidade
criarEncomenda({ id: 1 });
// @ts-expect-error quantidade tem de ser number
criarEncomenda({ id: 1, quantidade: "2" });
// @ts-expect-error propriedade a mais num literal
criarEncomenda({ id: 1, quantidade: 2, desconto: 5 });

function assertIgual<T>(real: T, esperado: T): void {
  const r = JSON.stringify(real);
  const e = JSON.stringify(esperado);
  if (r !== e) throw new Error("esperado " + e + ", obtido " + r);
}

function teste(nome: string, corpo: () => void): void {
  try {
    corpo();
    console.log("ok    " + nome);
  } catch (e) {
    console.log("FALHA " + nome + ": " + (e as Error).message);
  }
}

function iniciais(nome: string): string {
  return nome.split(" ").map((p) => p[0].toUpperCase()).join("");
}

teste("duas palavras", () => assertIgual(iniciais("ana silva"), "AS"));
teste("espaço duplo", () => assertIgual(iniciais("ana  silva"), "AS"));
// ok    duas palavras
// FALHA espaço duplo: Cannot read properties of undefined (reading 'toUpperCase')

// Um teste com o tipo errado nem compila (TS2345: number vs string):
// @ts-expect-error
teste("tipo errado", () => assertIgual(iniciais("ana"), 1));

