// Em vez de: enum Estado { Ativo, Suspenso }
const Estado = { Ativo: "ativo", Suspenso: "suspenso" } as const;
type Estado = (typeof Estado)[keyof typeof Estado]; // "ativo" | "suspenso"

// Em vez de: constructor(public nome: string) {}
class Cliente {
  nome: string;
  estado: Estado;
  constructor(nome: string, estado: Estado) {
    this.nome = nome;
    this.estado = estado;
  }
}

const c = new Cliente("Rita", Estado.Suspenso);
console.log(c.nome, c.estado); // Rita suspenso

