type DiaUtil = "seg" | "ter" | "qua" | "qui" | "sex";

function agendar(dia: DiaUtil, hora: number): string {
  return dia + " " + hora + "h";
}

// Positivo: tem de compilar.
const ok: string = agendar("qua", 10);

// @ts-expect-error sábado não é dia útil
agendar("sab", 10);
