function contarPalavras(texto: string): Record<string, number> {
  const contagem: Record<string, number> = {};
  for (const p of texto.toLowerCase().split(/\s+/)) {
    if (p === "") continue;
    contagem[p] = (contagem[p] ?? 0) + 1;
  }
  return contagem;
}

type tipos = [Esperar<Igual<ReturnType<typeof contarPalavras>, Record<string, number>>>];

teste("frase simples", () => assertIgual(contarPalavras("olá mundo"), { "olá": 1, mundo: 1 }));
teste("repetidas", () => assertIgual(contarPalavras("Sim  sim NÃO"), { sim: 2, "não": 1 }));
teste("só espaços", () => assertIgual(contarPalavras("   "), {}));
// ok    frase simples
// ok    repetidas
// ok    só espaços
